window.room=(()=>{const checkbox=document.querySelector('#reduce'),media=matchMedia('(prefers-reduced-motion:reduce)'),listeners=new Set();const reduced=()=>checkbox.checked||media.matches;function change(){document.body.classList.toggle('reduced',reduced());for(const fn of listeners)fn(reduced())}checkbox.addEventListener('change',change);media.addEventListener('change',change);document.querySelector('#reset').addEventListener('click',()=>dispatchEvent(new Event('room-reset')));addEventListener('message',e=>{if(e.source!==parent||(location.protocol!=='file:'&&e.origin!==location.origin))return;if(['reset','reset-demo'].includes(e.data?.type))document.querySelector('#reset').click();if(['motion-prefs','motion-preference'].includes(e.data?.type)){checkbox.checked=!!e.data.reduced;change()}});change();return{reduced,onPreference:fn=>listeners.add(fn),announce:text=>{document.querySelector('#state').textContent=text;parent.postMessage({type:'demo-state',state:text},'*')}}})();
